#include <iostream>
#include <bitset>

using namespace std;

const int max_p = 1000000;
const long modulo = 1000000007;

void mark_orbit(bitset<max_p>& visited, int start, long long k, long long p) {
    long long cur = (start * k) % p;
    while (cur != start) {
        visited[cur] = true;
        cur = (cur * k) % p;
    }
}

int main() {
    long long p, k;
    cin >> p >> k;

    if (k != 1 && k != 0) {
        bitset<max_p> visited;
        long long answer = 1;
        for (int i = 1; i < p; ++i) {
            if (!visited[i]) {
                mark_orbit(visited, i, k, p);
                answer = (answer * p) % modulo;
            }
        }
        cout << answer << endl;
    } else if (k == 1) {
        long long answer = 1;
        for (int i = 0; i < p; ++i)
            answer = (answer * p) % modulo;
        cout << answer << endl;
    } else {
        long long answer = 1;
        for (int i = 0; i < p - 1; ++i)
            answer = (answer * p) % modulo;
        cout << answer << endl;
    }
    return 0;
}
